class Solution {
public:
    vector<int> sumOfDistancesInTree(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        vector<int> count(n, 1);
        vector<long long> res(n, 0);
        vector<int> parent(n, -1);
        vector<int> order;
        order.reserve(n);
        vector<bool> visited(n, false);
        vector<int> stk;
        stk.reserve(n);
        stk.push_back(0);
        visited[0] = true;
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    stk.push_back(v);
                }
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            for (int v : adj[u]) {
                if (v != parent[u]) {
                    count[u] += count[v];
                    res[u] += res[v] + count[v];
                }
            }
        }

        vector<long long> ans(n);
        ans[0] = res[0];
        for (int i = 1; i < n; i++) {
            int u = order[i];
            int p = parent[u];
            ans[u] = ans[p] - count[u] + (n - count[u]);
        }

        return vector<int>(ans.begin(), ans.end());
    }
};
